package io.github.diodeme.ji.host.web;

/**
 * Hands a URI to the user's platform browser (chapter 18 §1). The desktop startup entry uses it to open
 * the PWA this Host serves itself; the Host process never spawns a second web server.
 */
@FunctionalInterface
public interface BrowserLauncher {
    /**
     * @return {@code true} when the platform accepted the URI; {@code false} when this machine has no
     *         desktop browser, so the caller can fall back to showing the address
     */
    boolean open(URI uri);

    /** Opens URIs with the platform default browser using structured argv, never a shell string. */
    static BrowserLauncher system() { return new SystemBrowserLauncher(); }
}
```

